add_action( 'woocommerce_product_options_pricing', 'perfectpixel_sale_percentage_field' );
add_action( 'woocommerce_admin_process_product_object', 'perfectpixel_sale_percentage_save', 20 );

function perfectpixel_sale_percentage_field() {
	$options = array( '' => '—' );
	foreach ( wp_parse_id_list( '{{sale_percent_options}}' ) as $percent ) {
		if ( $percent > 0 && $percent < 100 ) {
			$options[ $percent ] = $percent . '%';
		}
	}
	woocommerce_wp_select(
		array(
			'id'          => '_perfectpixel_sale_percent',
			'label'       => 'Έκπτωση %',
			'options'     => $options,
			'desc_tip'    => true,
			'description' => 'Η τιμή προσφοράς υπολογίζεται από την κανονική τιμή με την αποθήκευση. Επιλέξτε — για χειροκίνητη τιμή προσφοράς.',
		)
	);
}

function perfectpixel_sale_percentage_save( $product ) {
	if ( ! isset( $_POST['_perfectpixel_sale_percent'] ) || ! $product->is_type( array( 'simple', 'external' ) ) ) {
		return;
	}
	$percent = absint( $_POST['_perfectpixel_sale_percent'] );
	$product->update_meta_data( '_perfectpixel_sale_percent', $percent ? $percent : '' );
	$regular = (float) $product->get_regular_price( 'edit' );
	if ( $percent > 0 && $percent < 100 && $regular > 0 ) {
		$product->set_sale_price( wc_format_decimal( $regular * ( 1 - $percent / 100 ), wc_get_price_decimals() ) );
	}
}
